    fun findResponse(hsfzRequestHex: String): String? {
        val clean = hsfzRequestHex.trim().uppercase()
        authenticTraces[clean]?.let { return it }
        // Also match without length prefix (by UDS payload and target)
        if (clean.length >= 16) {
            val targetAndPayload = clean.substring(14)
            for ((req, resp) in authenticTraces) {
                if (req.length >= 16 && req.substring(14) == targetAndPayload) {
                    return resp
                }
            }
        }
        return null
    }
